        # Find leftmost 4 in this row during shape area
        left = None
        right = None
        for c in range(len(grid[0])):
            if grid[r][c] == 4:
                if left is None:
                    left = c
                right = c
        if left is not None and right is not None and left != right:
            # Fill between left and right with 4s
            for c in range(left, right + 1):
                if grid[r][c] == 1:
                    result[r][c] = 4
    return result

